  `max_discount_amount` decimal(15,2) DEFAULT NULL COMMENT 'Mức giảm tối đa (Dành riêng cho loại PERCENTAGE)',
  `usage_limit` int DEFAULT NULL COMMENT 'Tổng số lượt sử dụng tối đa của mã này',
