  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `customer_group` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exchange_points` int DEFAULT NULL,
  `target_email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_voucher_code` (`voucher_code`),
  KEY `idx_active_date` (`is_active`,`start_date`,`end_date`)
